"""Update documentation only after the measured acceptance has been finalized."""
from pathlib import Path
import json
REPO=Path(__file__).resolve().parents[3]
def main():
    m=json.loads((REPO/'docs/dvizhok-stage-036-measurements.json').read_text())
    assert m['coverage']['assessedMethods']==38 and m['regression']['successful']
    count=m['regression']['testsRun'];mutations=m['mutations']
    p=REPO/'docs/tasks/036-dvizhok-form-effects.md';s=p.read_text().replace('Статус: **подготовлено к реализации**, 2 октября 2026 года.','Статус: **реализовано и проверено**, 3 октября 2026 года.',1)
    s+=f'''\n## Финальная проверка\n\nРеализован общий opt-in formEffects: синхронная запись текущего объекта через\nпрежнее storage, типизированные запросы открытия по YAML и явно объявленный\nlifecycle целевого контекста. Бизнес-логика остаётся исходным XBSL; Python\nне рассчитывает перенос/итоги. SQL-снимки каждой фиксации строятся SELECT\nпо фактической БД и независимо читаются административным аудитором.\n[Технический контракт](../form-effects.md) фиксирует ограничения standalone.\n\nПубличные test/run дали каждый **46/46 PASS**, совпали наблюдения/баллы,\nвыполнены три новых прямых корня в memory/PostgreSQL.\n[Карта](../dvizhok-coverage-after-036.md) подтверждает **38/44** с сохранением\nпрежних 35 методов. Свежие прежние задания: 74 PASS + 3 ожидаемых UNSUPPORTED\nдля №34, 70 PASS для №35, 22 PASS для прежних бизнес-критериев.\n\nПолная последовательная регрессия: **{count}/{count} без пропусков**, включая\nвсе прежние 246 тестов. {mutations} временных мутаций дали независимый FAIL;\nдва переносимых проекта проверили имена/namespace/alias, собственные методы,\nзатенение и snapshots. Два свежих batch дали каждый 2 passed / 1 failed и\nнулевой cacheHit. SQL-сбой остался ERROR; проверены отказ до/после записи для\nновых/существующих объектов, успешный следующий критерий, поздняя ошибка и\nвнешний rollback в обоих backend.\n\nПервичная приёмка содержала ошибки fixtures (native имя исключения,\nнедостижимый код и YAML anchors), а проверка исходных методов выявила\nкомпоновку lifecycle без alias. Первичные журналы сохранены; исправленные\nповторы успешны. В первом полном прогоне 265 тестов прошли, один прежний
тест публичных команд №35 получил три timeout 5s. Его отдельный повтор и
финальный полный прогон прошли с прежними лимитами. Лимиты не увеличивались,\nпрежние тесты не удалялись.\n\nЧетыре validate прошли; grading/batch/manifest/events соответствуют JSON Schema.\nSHA-256 всех четырёх исходных архивов сохранён; тестовых контейнеров/сетей\nпосле приёмки нет. Свидетельства — result/dvizhok-form-effects,\n[измерения](../dvizhok-stage-036-measurements.json); воспроизведение —\n[README корпуса](../../tests/corpus/form-effects/README.md).\n\nПо-прежнему остаются шесть прямых бизнес-корней, полные YAML/UI критерии,\nплатформенная компиляция и браузерные сценарии. Вызванные два helper Отгрузки\nне получили собственной прямой оценки.\n'''
    p.write_text(s)
    p=REPO/'README.md';s=p.read_text();a=s.index('Следующее [задание №36]')
    s=s[:a]+f'''[Задание №36](docs/tasks/036-dvizhok-form-effects.md) реализовано:\nявный formEffects включает запись текущего объекта и типизированный запрос\nоткрытия с detached снимками и opt-in lifecycle. Storage и исходные\nПередЗаписью/ПослеЗаписи переиспользуются; PostgreSQL независимо проверяет\nкаждую фиксацию. [Контракт](docs/form-effects.md).\n\n```sh\nbin/element-test test --project Dvizhok.xdump \\\n  --assignment assignments/dvizhok-form-effects \\\n  --output result/dvizhok-form-effects/test --integration\n```\n\nПриёмка №36: test/run — по **46/46**, полная Docker/SQL-регрессия —\n**{count}/{count} без пропусков**. [Карта 38/44](docs/dvizhok-coverage-after-036.md)\nсохраняет прежние 35 методов; [измерения](docs/dvizhok-stage-036-measurements.json)\nподтверждают мутации, переносимость, batch и неизменность архивов.\nШесть прямых бизнес-корней, YAML-привязки и браузерный UI — следующие этапы.\n'''
    s=s.replace('Записать/Открыть из формы, вычисление YAML-выражений и браузерный UI недоступны.', 'Без formEffects Записать/Открыть из формы недоступны; вычисление YAML-выражений и браузерный UI не реализованы.')
    p.write_text(s)
    p=REPO/'docs/next-task.md';s=p.read_text();a=s.index('## Реализация задания №35')
    s=f'''# Следующий этап: оставшиеся шесть прямых бизнес-корней Dvizhok\n\n[Задание №36](tasks/036-dvizhok-form-effects.md) реализовано и проверено.\nПубличные test/run дали каждый 46 PASS; полный Docker/SQL прогон —\n{count} успешных тестов без пропусков. [Карта](dvizhok-coverage-after-036.md)\nподтверждает **38/44** независимо оценённых методов, включая прежние 35.\n[Контракт эффектов](form-effects.md), [измерения](dvizhok-stage-036-measurements.json).\n\nСледующий приоритет — собственные прямые критерии для Отгрузка.\nПриСозданииНаОсновании, трёх финансовых ПриСозданииНаОсновании и двух helper\nОтгрузки: СоздатьЧасть и ПеренестиТабличнуюЧасть. Их вызов через форму уже\nнаблюдался, но не заменяет прямую независимую оценку. Нужны typed fixtures\nоснований, проверка всех переносимых полей/строк/ссылок и независимые мутации.\n\n№36 сохраняет ограниченный standalone адаптер: синхронная запись через\nstorage и detached запросы открытия. Нет браузерного UI, YAML-привязок\nтаблицы или неявного связывания нового документа с Объект целевой формы.\nОтдельно остаются критерии всех 75/75 файлов, платформенная компиляция и UI.\nЗАПОЛНИТЬ/JOIN других архивов, LMS, HTTP и деплой остаются отложенными.\n\n'''+s[a:]
    p.write_text(s)
    p=REPO/'docs/roadmap.md';s=p.read_text();a=s.index('Текущий приоритет пользователя');b=s.index('\n| Этап |',a)
    s=s[:a]+f'''Текущий приоритет пользователя — полная проверка Dvizhok.xdump.\n[Карта после №36](dvizhok-coverage-after-036.md) содержит 75 файлов / 44 метода\nи **38 независимо оценённых методов**. №34 добавил контекст семи форм,\n№35 — константы и календарь, №36 — два архивирования с записью и запрос\nоткрытия отгрузки. Публичная приёмка №36 — 46 PASS в каждом test/run;\nполная регрессия — {count} успешных тестов с Docker/SQL без пропусков.\n[Измерения](dvizhok-stage-036-measurements.json) сохраняют факты, первичные\nсбои и успешные повторы. Далее — шесть прямых бизнес-корней и критерии\nдекларативного интерфейса; ЗАПОЛНИТЬ для ДемоСРМ отложено.\n'''+s[b:]
    s=s.replace('[№36](tasks/036-dvizhok-form-effects.md) подготовлен для трёх эффектов форм','[№36](tasks/036-dvizhok-form-effects.md) добавил три корня эффектов форм (38/44)')
    s=s.replace('после №35 проверены 246 разных тестов','после №36 проверены '+str(count)+' разных тестов')
    p.write_text(s)
    print('Task 36 report, README, roadmap and next-task updated')
if __name__=='__main__':main()
